/* Mã CSS đặt ở đây sẽ áp dụng cho mọi giao diện */

body, #content, .mw-body, .mw-body-content {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
}

a {
    color: #8ab4f8 !important;
}

a:visited {
    color: #c58af9 !important;
}

/* Mã CSS đặt ở đây sẽ áp dụng cho mọi giao diện */

@import url('https://static.klaviyo.com/fonts/Bebas-Neue-Klaviyo-Hosted.css');

body, .mw-parser-output {
    font-family: 'Bebas Neue Klaviyo Hosted', sans-serif !important;
}

