/* aresvn Pseudo Dark Mode */
body.aresvn-dark {
  background: #0e0e11;
  color: #e6e6eb;
}

/* Invert everything INSIDE content */
body.aresvn-dark .mw-parser-output * {
  filter: invert(1) hue-rotate(180deg);
}

/* EXCLUDE images & media */
body.aresvn-dark img,
body.aresvn-dark video,
body.aresvn-dark svg,
body.aresvn-dark canvas,
body.aresvn-dark iframe {
  filter: none !important;
}

