/* Genesis collapsible image swap */
.aresvn-genesis .aresvn-img-collapsed {
  display: block;
}

.aresvn-genesis .aresvn-img-expanded {
  display: none;
}

/* Khi đang mở, MediaWiki sẽ đổi từ mw-collapsed -> mw-expanded */
.aresvn-genesis.mw-expanded .aresvn-img-collapsed {
  display: none;
}

.aresvn-genesis.mw-expanded .aresvn-img-expanded {
  display: block;
}

