/* AresVN collapsible image swap */
.aresvn-collapse .aresvn-img-collapsed {
  display: block;
}

.aresvn-collapse .aresvn-img-expanded {
  display: none;
}

.aresvn-collapse:not(.mw-collapsed) .aresvn-img-collapsed {
  display: none;
}

.aresvn-collapse:not(.mw-collapsed) .aresvn-img-expanded {
  display: block;
}

.aresvn-collapse::after,
.aresvn-collapse .mw-collapsible-content::after {
  content: "";
  display: block;
  clear: both;
}

