/*.wiki-hover-container:hover .hover-image {*/
/*    opacity: 1 !important;*/
/*}*/

/* Hiệu ứng Hover Swipe từ giữa ra 2 bên Top/Bottom */
.wiki-hover-container {
  position: relative;
  display: inline-block;
  overflow: hidden;
}

.wiki-hover-container .main-image {
  display: block;
}

.wiki-hover-container .hover-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  /* Thu hẹp ảnh về đường gạch ngang ở giữa */
  clip-path: inset(50% 0 50% 0);
  transition: clip-path 0.4s ease-in-out;
  pointer-events: none;
}

.wiki-hover-container:hover .hover-image {
  /* Mở rộng lên trên và xuống dưới hoàn toàn */
  clip-path: inset(0 0 0 0);
}

