$(document).ready(function() {
    // Chỉ chạy trong các trang đọc bài viết bình thường (Namespace chính = 0)
    if ( mw.config.get('wgNamespaceNumber') === 0 && mw.config.get('wgAction') === 'view' ) {
        // Nếu trang chưa có mục lục (.toc) và có ít nhất 1 tiêu đề (h2, h3, h4...)
        if ( $('.toc').length === 0 && $(':header').length > 0 ) {
            // Kiểm tra xem trang có bị cố tình ẩn mục lục bằng __NOTOC__ không
            if ( !$('body').hasClass('no-toc') ) {
                // Tạo yêu cầu ép hệ thống tải lại trang kèm mục lục
                var tocPromise = mw.loader.using('mediawiki.toc');
                // Đoạn mã này sẽ kích hoạt tính năng hiển thị mục lục của MediaWiki
            }
        }
    }
});

