/* Tự động kích hoạt hiển thị mục lục cho mọi trang nếu có ít nhất 1 tiêu đề */
$(document).ready(function() {
    // Chờ TweekiTOC tải xong giao diện Bootstrap
    setTimeout(function() {
        // Kiểm tra xem có menu TweekiTOC trên trang không và bài viết có thẻ h4 không
        if ($('#tweeki-toc').length > 0 && $('h4').length > 0) {

            // Duyệt qua từng tiêu đề cấp 4 trên trang để tự chèn vào menu con của cấp 3
            $('h4').each(function() {
                var h4_id = $(this).attr('id');
                var h4_text = $(this).find('.mw-headline').text() || $(this).text();

                if (h4_id) {
                    // Tìm tiêu đề cấp 3 đứng ngay trước nó để bỏ vào đúng nhóm
                    var parent_h3 = $(this).prevAll('h3').first();
                    var h3_id = parent_h3.attr('id');

                    if (h3_id) {
                        // Tìm link tương ứng của cấp 3 trong menu TweekiTOC
                        var $h3_menu_link = $('#tweeki-toc a[href="#' + h3_id + '"]');
                        var $h3_menu_item = $h3_menu_link.parent('li');

                        // Nếu cấp 3 chưa có danh sách con (ul), tạo mới một cái
                        if ($h3_menu_item.find('ul').length === 0) {
                            $h3_menu_item.append('<ul class="nav"></ul>');
                        }

                        // Chèn menu cấp 4 vào dưới cấp 3
                        $h3_menu_item.find('ul').first().append(
                            '<li class="nav-item tweeki-toc-level-4">' +
                            '<a class="nav-link" href="#' + h4_id + '">' + h4_text + '</a>' +
                            '</li>'
                        );
                    }
                }
            });

            // Cập nhật lại tính năng cuộn theo dõi (Scrollspy) của Bootstrap nếu cần
            $('body').scrollspy('refresh');
        }
    }, 500); // Trì hoãn nửa giây để đảm bảo Tweeki đã dựng xong menu gốc
});

