/* Tự động kích hoạt hiển thị mục lục cho mọi trang nếu có ít nhất 1 tiêu đề */
/* TỰ ĐỘNG CHÈN TIÊU ĐỀ CẤP 4 (====) VÀO MENU TWEEKI TOC */
(function () {
    function injectH4ToTweekiTOC() {
        // Kiểm tra xem TweekiTOC đã được sinh ra trên giao diện chưa
        var $tweekiToc = $('#tweeki-toc');
        if ($tweekiToc.length === 0 || $tweekiToc.find('ul').length === 0) {
            // Nếu chưa thấy, chờ thêm 1000ms rồi kiểm tra lại (Cơ chế lặp an toàn)
            setTimeout(injectH4ToTweekiTOC, 1000);
            return;
        }

        // Nếu trang không có thẻ h4 nào thì dừng lại luôn cho nhẹ máy
        var $h4s = $('h4');
        if ($h4s.length === 0) return;

        // Bắt đầu cào thẻ h4 để tự động nhét vào menu
        $h4s.each(function () {
            var h4Id = $(this).attr('id');
            // Lấy tên hiển thị của tiêu đề h4
            var h4Text = $(this).find('.mw-headline').text() || $(this).text();

            if (h4Id) {
                // Tìm thẻ h3 (cấp ===) đứng ngay trước thẻ h4 này
                var $parentH3 = $(this).prevAll('h3').first();
                var h3Id = $parentH3.attr('id');

                if (h3Id) {
                    // Tìm đến đúng vị trí của thẻ h3 đó trong menu TweekiTOC
                    var $h3Link = $tweekiToc.find('a[href="#' + h3Id + '"]');
                    var $h3Li = $h3Link.parent('li');

                    if ($h3Li.length > 0) {
                        // Nếu thẻ h3 này trong menu chưa có danh sách con (ul) để chứa cấp 4
                        var $subUl = $h3Li.children('ul');
                        if ($subUl.length === 0) {
                            $h3Li.append('<ul class="nav" style="padding-left: 15px; font-size: 0.9em;"></ul>');
                            $subUl = $h3Li.children('ul');
                        }

                        // Kiểm tra xem tiêu đề h4 này đã được chèn chưa để tránh bị trùng lặp
                        if ($subUl.find('a[href="#' + h4Id + '"]').length === 0) {
                            $subUl.append('<li class="nav-item"><a class="nav-link" href="#' + h4Id + '" style="color: #888; padding: 2px 0;">• ' + h4Text + '</a></li>');
                        }
                    }
                }
            }
        });

        // Kích hoạt lại tính năng theo dõi vị trí cuộn chuột của Bootstrap
        if (typeof $('body').scrollspy === 'function') {
            $('body').scrollspy('refresh');
        }
    }

    // Chạy hàm ngay khi trình duyệt sẵn sàng
    $(document).ready(function() {
        injectH4ToTweekiTOC();
    });
})();

