/* Tự động kích hoạt hiển thị mục lục cho mọi trang nếu có ít nhất 1 tiêu đề */
$(document).ready(function() {
    // Hàm này sẽ tự động chạy để kiểm tra và chèn tiêu đề cấp 4 vào cấu trúc HTML thực tế của bạn
    function fixTweekiTOCLevel4() {
        var $tweekiToc = $('#tweekiTOC #toc');

        // Nếu chưa tìm thấy menu mục lục xuất hiện trên trang, kiểm tra lại sau 100ms
        if ($tweekiToc.length === 0 || $tweekiToc.find('ul').length === 0) {
            setTimeout(fixTweekiTOCLevel4, 100);
            return;
        }

        // Tìm tất cả các thẻ h4 (cấp ====) thực tế có trên trang bài viết
        var $h4s = $('h4');
        if ($h4s.length === 0) return;

        $h4s.each(function() {
            var h4Id = $(this).attr('id');
            // Lấy nội dung chữ của tiêu đề cấp 4
            var h4Text = $(this).find('.mw-headline').text() || $(this).text();

            if (h4Id) {
                // Tìm thẻ h3 (cấp ===) đứng ngay trước thẻ h4 này để biết nó thuộc về mục con nào
                var $parentH3 = $(this).prevAll('h3').first();
                var h3Id = $parentH3.attr('id');

                if (h3Id) {
                    // Định vị thẻ <a> của cấp 3 trong menu dựa theo id href của nó
                    var $h3Link = $tweekiToc.find('a[href="#' + h3Id + '"]');
                    var $h3Li = $h3Link.parent('li.toclevel-2');

                    if ($h3Li.length > 0) {
                        // Nếu cấp 3 này trong menu chưa có danh sách con (ul) để chứa cấp 4, tạo mới một cái
                        var $subUl = $h3Li.children('ul');
                        if ($subUl.length === 0) {
                            $h3Li.append('<ul class="nav flex-column" style="padding-left: 20px; font-size: 0.9em; list-style-type: disc;"></ul>');
                            $subUl = $h3Li.children('ul');
                        }

                        // Nếu tiêu đề cấp 4 này chưa từng được chèn, tiến hành append nó vào HTML
                        if ($subUl.find('a[href="#' + h4Id + '"]').length === 0) {
                            $subUl.append(
                                '<li class="toclevel-3" style="display: block !important;">' +
                                '<a href="#' + h4Id + '" class="nav-link" style="padding: 2px 0; color: #aaa !important;">' + h4Text + '</a>' +
                                '</li>'
                            );
                        }
                    }
                }
            }
        });
    }

    // Kích hoạt hàm chạy ngay khi trang tải xong
    fixTweekiTOCLevel4();
});

