/* ==========================================================================
   TỰ ĐỘNG XỬ LÝ MỤC LỤC TWEEKI THEO LIMIT CỦA BẢN MẪU
   ========================================================================== */
$(document).ready(function() {
    function fixTweekiTOCLevel4() {
        // 1. ĐIỀU KIỆN: Chỉ xử lý nếu trên trang có sự xuất hiện của class .toclimit-4
        if ($('.toclimit-4').length === 0) {
            return; 
        }

        var $tweekiToc = $('#tweekiTOC #toc, #toc');

        // Nếu chưa tìm thấy menu mục lục, kiểm tra lại sau 1000ms
        if ($tweekiToc.length === 0 || $tweekiToc.find('ul').length === 0) {
            setTimeout(fixTweekiTOCLevel4, 1000);
            return;
        }

        // Tìm tất cả các thẻ h4 (cấp ====) thực tế trên bài viết
        var $h4s = $('h4');
        if ($h4s.length === 0) return;

        $h4s.each(function() {
            var h4Id = $(this).attr('id');
            var h4Text = $(this).find('.mw-headline').text() || $(this).text();

            if (h4Id) {
                // Tìm thẻ h3 đứng ngay trước thẻ h4 này
                var $parentH3 = $(this).prevAll('h3').first();
                var h3Id = $parentH3.attr('id');

                if (h3Id) {
                    // CỨU TINH Ở ĐÂY: Dùng .filter() để so sánh chuỗi thô, triệt tiêu hoàn toàn lỗi querySelector
                    var $h3Link = $tweekiToc.find('a').filter(function() {
                        return $(this).attr('href') === '#' + h3Id;
                    });

                    var $h3Li = $h3Link.parent('li.toclevel-2');

                    if ($h3Li.length > 0) {
                        var $subUl = $h3Li.children('ul');
                        if ($subUl.length === 0) {
                            // Tạo sub-menu ul mới cho cấp 4
                            $h3Li.append('<ul class="nav flex-column sub-level-4" style="padding-left: 20px; font-size: 0.9em; list-style-type: disc;"></ul>');
                            $subUl = $h3Li.children('ul');
                        }

                        // Kiểm tra xem liên kết h4 này đã được chèn chưa bằng so sánh chuỗi thô
                        var $exists = $subUl.find('a').filter(function() {
                            return $(this).attr('href') === '#' + h4Id;
                        });

                        if ($exists.length === 0) {
                            // Chèn thẻ li cấp 4 kèm class .show-level-4 để CSS hiển thị
                            $subUl.append(
                                '<li class="toclevel-3 show-level-4">' +
                                '<a href="#' + h4Id + '" class="nav-link">' + h4Text + '</a>' +
                                '</li>'
                            );
                        }
                    }
                }
            }
        });
    }

    // Kích hoạt chạy hàm
    fixTweekiTOCLevel4();
});

