/* ==========================================================================
   BẬT HIỂN THỊ SUB-MENU TWEEKI KHI CÓ TOCLIMIT-4
   ========================================================================== */
$(document).ready(function() {
	console.log("ready");
    // 1. Kiểm tra nhanh xem trang có gọi bản mẫu limit=4 không
    if ($('.toclimit-4').length > 0) {
    	console.log("found toclimit");

        // 2. Chờ mục lục Tweeki tải xong (khoảng 500ms) rồi ép hiện thẳng cái ul con lên
        setTimeout(function() {
            var $subMenus = $('#tweekiTOC #toc ul > li > ul, #toc ul > li > ul');

            if ($subMenus.length > 0) {
            	console.log("found submenu");
                // Ép cứng thuộc tính bằng css() để đè bẹp dí cái display: none của Tweeki
                $subMenus.attr('style', function(i, s) {
                    return (s || '') + 'display: block !important;';
                });
            }
        }, 500);

    }
});

